# Accepts a list of [id, p_id]; returns list of [id, type]

def classify_tree_nodes(nodes):
    # Gather all ids that are used as a parent
    parent_ids = set()
    for node in nodes:
        pid = node[1]
        if pid is not None:
            parent_ids.add(pid)

    result = []
    for node in nodes:
        node_id, pid = node
        if pid is None:
            node_type = "Root"
        elif node_id in parent_ids:
            node_type = "Inner"
        else:
            node_type = "Leaf"
        result.append([node_id, node_type])
    return result
